# Generated by eightfold/build/node_code.py from eightfold/build/tiering.py. Do not edit here.
from datetime import date

CRITERIA = {'version': '0.1-calibration',
 'weights': {'industry': 25, 'headcount': 20, 'open_reqs': 25, 'hcm': 20, 'geography': 10},
 'required': ['industry', 'headcount', 'open_reqs', 'hcm', 'geography'],
 'target_verticals': ['Healthcare',
                      'Insurance & Financial Services',
                      'Semiconductors & Advanced Manufacturing'],
 'excluded_verticals': [],
 'min_employees': 10000,
 'min_open_reqs': 500,
 'hcm_supported': ['Workday',
                   'SAP SuccessFactors',
                   'Oracle HCM',
                   'Taleo',
                   'iCIMS',
                   'Greenhouse',
                   'SmartRecruiters',
                   'Avature',
                   'Phenom'],
 'target_countries': ['United States'],
 'tier1_min': 80,
 'tier2_min': 60}

def _tri(value, test):
    """Apply test to value, preserving None as unknown."""
    return None if value is None else bool(test(value))

def evaluate(facts, c=CRITERIA):
    """facts: dict with vertical, employees, open_reqs, hcm (list|None), country,
    disqualifier (str|None). Returns the scored row, never raises on missing data."""
    checks = {
        "industry":  _tri(facts.get("vertical"), lambda v: v in c["target_verticals"]),
        "headcount": _tri(facts.get("employees"), lambda v: v >= c["min_employees"]),
        "open_reqs": _tri(facts.get("open_reqs"), lambda v: v >= c["min_open_reqs"]),
        "hcm":       _tri(facts.get("hcm"), lambda v: any(h in c["hcm_supported"] for h in v)),
        "geography": _tri(facts.get("country"), lambda v: v in c["target_countries"]),
    }
    w = c["weights"]
    fit = sum(w[k] for k, ok in checks.items() if ok is True)
    best_case = fit + sum(w[k] for k, ok in checks.items() if ok is None)
    missing = [k for k in c["required"] if checks[k] is None]

    reasons = []
    for k, ok in checks.items():
        tag = {True: "+", False: "-", None: "?"}[ok]
        reasons.append(f"{tag}{k}({w[k]})")

    if facts.get("disqualifier"):
        tier = "Excluded"
    elif facts.get("vertical") in c["excluded_verticals"]:
        tier = "Excluded"
    elif facts.get("identity_unresolved"):
        tier = "Review"
        missing = ["identity"] + missing
    elif missing:
        tier = "Review"
    elif fit >= c["tier1_min"]:
        tier = "Tier 1"
    elif fit >= c["tier2_min"]:
        tier = "Tier 2"
    else:
        tier = "Tier 3"

    return {
        "fit_score": fit,
        "fit_best_case": best_case,
        "fit_tier": tier,
        "missing_required_fields": ";".join(missing),
        "score_reasons": " ".join(reasons),
        "intent_score": facts.get("intent_score"),
        "engagement_score": facts.get("engagement_score"),
        "score_version": c["version"],
        "scored_at": facts.get("as_of", date.today().isoformat()),
        **{f"check_{k}": {True: "yes", False: "no", None: "unknown"}[v] for k, v in checks.items()},
    }


def _num(v):
    try:
        return None if v in (None, "") else float(v)
    except (TypeError, ValueError):
        return None


# Product names PredictLeads (or a Claygent) may return that do mean the HCM / ATS itself.
# Matching is exact per comma-separated item: "Workday Financial Management" or
# "Workday Prism Analytics" are Workday products, but not evidence of Workday HCM.
HCM_ALIASES = {
    "Workday": ["workday", "workday hcm", "workday human capital management", "workday recruiting", "workday ats"],
    "SAP SuccessFactors": ["sap successfactors", "successfactors"],
    "Oracle HCM": ["oracle hcm", "oracle human capital management", "oracle human capital management (hcm)", "oracle hcm cloud"],
    "Taleo": ["taleo", "oracle taleo"],
    "iCIMS": ["icims"],
    "Greenhouse": ["greenhouse"],
    "SmartRecruiters": ["smartrecruiters"],
    "Avature": ["avature"],
    "Phenom": ["phenom", "phenom people"],
}


def _hcm_from(text):
    """Supported HCM / ATS names in a comma-separated technology list. Absence stays unknown."""
    if not text:
        return None
    items = {i.strip().lower() for i in str(text).split(",") if i.strip()}
    hits = [name for name, aliases in HCM_ALIASES.items()
            if name in CRITERIA["hcm_supported"] and items & set(aliases)]
    return hits or None


def _facts(context, hcm):
    return {
        "vertical": context.get_input("vertical"),
        "employees": _num(context.get_input("employee_count")),
        "open_reqs": _num(context.get_input("job_count")),
        "hcm": hcm,
        "country": context.get_input("country"),
        "disqualifier": None,
        "identity_unresolved": False,
        "as_of": "",
    }


def _out(r, hcm, open_reqs, source):
    return {
        "fit_score": r["fit_score"],
        "fit_best_case": r["fit_best_case"],
        "fit_tier": r["fit_tier"],
        "missing_required_fields": r["missing_required_fields"] or "none",
        "score_reasons": r["score_reasons"],
        "score_version": r["score_version"],
        "check_hcm": r["check_hcm"],
        "check_open_reqs": r["check_open_reqs"],
        "check_headcount": r["check_headcount"],
        "hcm_detected": ", ".join(hcm) if hcm else "unknown",
        "hcm_source": source,
        "open_reqs": -1 if open_reqs is None else open_reqs,
    }


def handler(context):
    hcm = _hcm_from(context.get_input("technologies_found"))
    facts = _facts(context, hcm)
    r = evaluate(facts)
    return _out(r, hcm, facts["open_reqs"], "PredictLeads technographics" if hcm else "none")
